package org.sleepwell.app;

import android.app.*;
import android.view.*;
import android.widget.*;
import java.time.ZoneId;
import java.util.*;
import java.util.function.*;

/** Supporting editor details, not another save boundary. All quantity/awake edits remain drafts. */
final class RecordEditorSheets {
    private static Dialog show(Activity activity,LinearLayout body){Dialog dialog=new Dialog(activity);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);ScrollView scroll=new ScrollView(activity);scroll.setFillViewport(false);scroll.addView(body);dialog.setContentView(scroll);dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);int width=Math.min(activity.getResources().getDisplayMetrics().widthPixels-Design.dp(activity,32),Design.dp(activity,440)),height=Math.max(Design.dp(activity,160),activity.getResources().getDisplayMetrics().heightPixels-Design.dp(activity,100));scroll.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.AT_MOST));dialog.getWindow().setLayout(width,Math.min(height,scroll.getMeasuredHeight()));return dialog;}
    private static LinearLayout body(Activity activity,String title){LinearLayout body=Design.col(activity);Design.pad(body,20,18);body.setBackground(Design.shape(activity,Design.CREAM,22));Design.text(body,title,22,600,Design.INK);Design.space(body,10);return body;}
    static Dialog tags(Activity activity,RecordDraft draft,Consumer<String> quantity,Runnable manage,Runnable add){LinearLayout body=body(activity,"Tag details");Design.text(body,"Return to the edit screen, then Save changes to keep quantities.",13,400,Design.MUTED);Design.space(body,14);final Dialog[] owned={null};
        if(draft.tags.isEmpty())Design.text(body,"Add a tag to attach a quantity.",14,400,Design.MUTED);
        for(String name:new ArrayList<>(draft.tags)){TagQuantity value=draft.quantities.get(name);LinearLayout row=Design.row(activity);row.setMinimumHeight(Design.dp(activity,64));LinearLayout copy=Design.col(activity);Design.text(copy,name,15,500,Design.INK);Design.text(copy,value==null?"Set quantity":value.display(),13,400,Design.MUTED);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));row.addView(new Design.Icon(activity,"chevron",Design.BROWN),new LinearLayout.LayoutParams(Design.dp(activity,20),Design.dp(activity,20)));row.setFocusable(true);row.setContentDescription("Set quantity for "+name+(value==null?"":", "+value.display()));row.setBackground(Design.touch(activity,android.graphics.Color.TRANSPARENT,12));row.setOnClickListener(v->{InteractionFeedback.action(v);owned[0].dismiss();quantity.accept(name);});body.addView(row);Design.line(body);}
        Design.space(body,10);Design.button(body,"Add tag",false,()->{owned[0].dismiss();add.run();});Design.button(body,"Manage saved tags",false,()->{owned[0].dismiss();manage.run();});Design.text(body,"Managing saved tags can also update your saved records.",12,400,Design.MUTED);Design.button(body,"Back to edit",true,()->owned[0].dismiss());owned[0]=show(activity,body);return owned[0];}
    static Dialog awake(Activity activity,RecordDraft draft,ZoneId zone,IntConsumer remove,Runnable add){LinearLayout body=body(activity,"Awake periods");Design.text(body,"Marked awake time is excluded from duration. Save changes to keep it.",13,400,Design.MUTED);Design.space(body,12);final Dialog[] owned={null};
        if(draft.awake.isEmpty())Design.text(body,"No awake periods added.",14,400,Design.MUTED);
        for(int n=0;n<draft.awake.size();n++){int index=n;RecordIntervals.Span span=draft.awake.get(n);LinearLayout row=Design.row(activity);row.setMinimumHeight(Design.dp(activity,56));LinearLayout copy=Design.col(activity);Design.text(copy,RecordUi.clock(activity,span.start,zone)+" – "+RecordUi.clock(activity,span.end,zone),15,500,Design.INK);Design.text(copy,RecordUi.duration(span.end-span.start)+" · awake",12,400,Design.MUTED);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));row.addView(Design.iconButton(activity,"close","Remove awake period "+(n+1),()->{owned[0].dismiss();remove.accept(index);}),new LinearLayout.LayoutParams(Design.dp(activity,48),Design.dp(activity,48)));body.addView(row);Design.line(body);}
        Design.button(body,"Add awake period",false,()->{owned[0].dismiss();add.run();});Design.button(body,"Back to edit",true,()->owned[0].dismiss());owned[0]=show(activity,body);return owned[0];}
    static Dialog about(Activity activity,RecordEntry record,ZoneId zone,String csvDetail){LinearLayout body=body(activity,"About this record");Design.text(body,record==null?"User-reported period · no sensor measurements.":record.provenance()+(record.manual()?" · no sensor measurements.":" · original measurements are preserved."),14,400,Design.MUTED);if(record!=null&&record.zone.isEmpty()){Design.space(body,12);Design.text(body,"Original time zone unavailable; shown in "+zone.getId()+".",13,400,Design.MUTED);}if(record!=null&&record.csvImported){Design.space(body,12);Design.text(body,csvDetail.isEmpty()?"Original CSV source details are available in Record options.":csvDetail,13,400,Design.MUTED);}final Dialog[] owned={null};Design.button(body,"Done",true,()->owned[0].dismiss());owned[0]=show(activity,body);return owned[0];}
    private RecordEditorSheets(){}
}
